  "red_flags": [
    {
      "type": "sublease_permitted",
      "quote": "\"B\" shall not transfer or provide as mortgage the right of lease nor sublet the object matter of lease to the 3rd party."
    },
    {
      "type": "tenant_break_option",
      "quote": "If \"B\" wishes to cancel the contract during the lease term, \"B\" shall notify \"A\" in writing 60 days in advance without fail. In this case, this contract is terminated on the 60th day from the day when \"A\" receives the written notification."
    },
    {
      "type": "tenant_break_option",
      "quote": "If \"B\" wishes to cancel the contract 60 days in advance in accordance with Clause 3 of Article 4, \"B\" shall pay \"A\" amount calculated at the interest rate of loan by stipulation of commercial bank against the guaranty money for the term ranging from the next day of contract cancellation to the 60th day, rent and management expenses."
    },
    {
      "type": "tenant_break_option",
      "quote": "However, the term for imposing penalty shall be until either the 60th day from the day when \"A\" receives written notification of contract cancellation or expiry date of lease contract, whichever comes earlier."
    },
    {
      "type": "tenant_break_option",
      "quote": "In case that this contract is cancelled in accordance with the Clause 2, the contract deposit paid by \"B\" shall be unconditionally in the possession of \"A\" as penalty and \"B\" is not entitled to claim restitution."
    },
    {
      "type": "tenant_break_option",
      "quote": "In case that this contract is terminated in accordance with Clause 2 of Article 4 and \"B\" completely fulfills the obligation stipulated in each provision of this contract, \"A\" shall return the deposited guaranty money. However, if any charges in the account of \"B\" such as unpaid rent, management expenses, etc. remain unsettled, \"A\" is entitled to deduct them from guaranty money so as to make balance, which will be actually returned."
    },
    {
      "type": "tenant_break_option",
      "quote": "Within 14 days after \"B\" completes restoring state of object matter of the lease, \"A\" shall return guaranty money. For delayed return of guaranty money, delay charge at the annual interest rate of 15% shall be imposed to \"A.\""
    },
    {
      "type": "tenant_break_option",
      "quote": "In case that \"B\" does not occupy and use the object matter of the lease notwithstanding elapse of 30 days after the commencing date of leas¢ term nor pay \"A\" the whole amount of guaranty money before the commencing date of lease term, this contract is regarded as automatically cancelled on the commencing date of lease term."
    }
  ]
